"""Environment access tracking for env_fingerprint."""

from __future__ import annotations

import hashlib
import os
from typing import Dict

_env_access: Dict[str, str] = {}
_original_getenv = os.getenv
_original_getitem = os.environ.__getitem__


def _hash_value(value: str) -> str:
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _record(name: str, value: str | None) -> None:
    if value is None:
        return
    if name not in _env_access:
        _env_access[name] = _hash_value(value)


def patched_getenv(key: str, default: str | None = None) -> str | None:
    value = _original_getenv(key, default)
