"""Supabase Storage downloads/uploads for run bundles and artifacts."""

from __future__ import annotations

import os
from pathlib import Path
from typing import Iterable

import requests


def _supabase_url() -> str:
    url = os.environ.get("SUPABASE_URL")
    if not url:
        raise RuntimeError("SUPABASE_URL not set")
    return url.rstrip("/")


def _base_headers() -> dict:
    key = os.environ.get("SUPABASE_SERVICE_ROLE_KEY")
    if not key:
        raise RuntimeError("SUPABASE_SERVICE_ROLE_KEY not set")
    return {"Authorization": f"Bearer {key}", "apikey": key}


def download_bundle(run_id: str, dest_dir: Path, filenames: Iterable[str]) -> None:
    dest_dir.mkdir(parents=True, exist_ok=True)
    for filename in filenames:
        url = f"{_supabase_url()}/storage/v1/object/run-bundles/{run_id}/{filename}"
        resp = requests.get(url, headers=_base_headers(), timeout=30)

